import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.CS-cBh1g.js";const g=JSON.parse('{"title":"Connect an agent","description":"","frontmatter":{},"headers":[],"relativePath":"agents/index.md","filePath":"agents/index.md"}'),o={name:"agents/index.md"};function i(h,e,r,d,l,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="connect-an-agent" tabindex="-1">Connect an agent <a class="header-anchor" href="#connect-an-agent" aria-label="Permalink to &quot;Connect an agent&quot;">​</a></h1><p>A coding agent (Claude Code, Codex or any agent that can run commands) can work your team&#39;s <a href="/Mayhem/suite/tasks">task queue</a>: read the feedback, investigate with the logs and the simulation, propose a plan in plain English, and change the robot code once a person approves. People stay in charge of two decisions: whether the plan is right, and whether the change is.</p><h2 id="put-an-agent-on-the-queue" tabindex="-1">Put an agent on the queue <a class="header-anchor" href="#put-an-agent-on-the-queue" aria-label="Permalink to &quot;Put an agent on the queue&quot;">​</a></h2><ol><li>In the app, choose the robot code folder.</li><li>Open <strong>Tasks → Connect an agent → Put an agent on the queue</strong> and copy the prompt. It has this robot&#39;s folder filled in.</li><li>Open your agent <strong>in the robot code folder</strong> and paste it.</li></ol><p>The agent then picks up the next task, proposes a plan, and waits for you. The line above the Tasks board names each agent on the queue and when it last did something.</p><div class="tip custom-block"><p class="custom-block-title">Keep it running</p><p>If the robot repo has the <code>mayhem-tasks</code> skill (in <code>.claude/skills/</code>), Claude Code can work the queue on a timer: <code>/loop 10m /mayhem-tasks</code>.</p></div><h2 id="give-it-mayhem-s-tools-mcp" tabindex="-1">Give it Mayhem&#39;s tools (MCP) <a class="header-anchor" href="#give-it-mayhem-s-tools-mcp" aria-label="Permalink to &quot;Give it Mayhem&#39;s tools (MCP)&quot;">​</a></h2><p>The agent works best with Mayhem&#39;s tools: reading tasks, analyzing logs, running the sim proof, diffing behavior. Add the Mayhem MCP server to your agent&#39;s configuration:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;">    &quot;mayhem&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;">&quot;node&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;">&quot;/absolute/path/to/Mayhem/scripts/mayhem.mjs&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;">&quot;mcp&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Use the path to a Mayhem checkout or to the extracted <code>Mayhem-suite-tools</code> folder from a release. It needs Node 24 or later. <strong>Tasks → Connect an agent → Connect over MCP</strong> shows the same setup with your path filled in.</p><p>Agents without MCP can call every tool from the shell: <code>node scripts/mayhem.mjs tool &lt;name&gt; &#39;&lt;JSON&gt;&#39;</code>. See <a href="/Mayhem/agents/tools">Command line and MCP tools</a>.</p><h2 id="other-panels-under-connect-an-agent" tabindex="-1">Other panels under Connect an agent <a class="header-anchor" href="#other-panels-under-connect-an-agent" aria-label="Permalink to &quot;Other panels under Connect an agent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Panel</th><th>Use</th></tr></thead><tbody><tr><td><strong>Share this project with an agent</strong></td><td>A brief describing the project, for a one-off request (&quot;add a second auto&quot;).</td></tr><tr><td><strong>Live file link</strong></td><td><strong>Save project file</strong> links the project to <code>robot.mayhem.json</code>, so an agent&#39;s edits show up in the app within a second.</td></tr><tr><td><strong>Command line</strong></td><td>The <code>scripts/mayhem.mjs</code> commands.</td></tr><tr><td><strong>C++ library</strong></td><td>Export the routines as a C++ header.</td></tr><tr><td><strong>Project document</strong></td><td>The raw project JSON.</td></tr></tbody></table><h2 id="what-agents-can-and-can-t-do" tabindex="-1">What agents can and can&#39;t do <a class="header-anchor" href="#what-agents-can-and-can-t-do" aria-label="Permalink to &quot;What agents can and can&#39;t do&quot;">​</a></h2><ul><li>They <strong>can</strong> edit robot code, the project file, machines and scenarios; run the simulation; read logs; and commit on their own branch.</li><li>They <strong>can&#39;t</strong> command the robot. Mayhem only reads NetworkTables, and the MCP tools never deploy.</li><li>They <strong>don&#39;t</strong> push to <code>main</code>. <code>main</code> is the known-good version, and putting it back on the robot is a button only people press.</li></ul><p>After an agent edits a routine, look at the field and the graph, and preview it before running it on the robot.</p>`,16)])])}const u=t(o,[["render",i]]);export{g as __pageData,u as default};
